tool.command:
        mkdir -p miadash_inputs miadash_outputs ;
        export MIADASH_OUTPUT_DIR=\$PWD/miadash_outputs ;
#if $abundance_table
        cp -f '$abundance_table' miadash_inputs/assay.tsv ;
#end if
#if $coldata_table
        cp -f '$coldata_table' miadash_inputs/coldata.tsv ;
#end if
#if $rowdata_table
        cp -f '$rowdata_table' miadash_inputs/rowdata.tsv ;
#end if
#if $row_tree
        cp -f '$row_tree' miadash_inputs/row.tree ;
#end if
        export MIADASH_TAXA_FROM_ROWNAMES='$taxa_from_rownames' ;
        exec /usr/local/bin/miadash-entrypoint

